6	import { useMiaPageContext } from '@/features/mia/hooks/useMiaPageContext';
7	
8	export default function Dashboard() {
9	  const deviceMode = useDeviceMode();
10	  const { loading, selectedStore } = useStore();
11	
12	  useMiaPageContext({
13	    description: 'Dashboard principal do Momma — KPIs consolidados, vendas do dia, status das lojas, gráficos analíticos.',
14	    natural_language_hints: '"hoje" = vendas/produção do dia atual; "comparar lojas" = grid multi-loja; "como tá indo" = KPIs principais. Use o seletor de loja no topo pra mudar contexto.',
15	    capabilities: ['consultar_kpis', 'comparar_lojas', 'ver_vendas_dia', 'navegar_para_modulos'],
16	    primary_entity: 'dashboard_consolidado',
17	  });
18	
19	  if (deviceMode === 'mobile') {
20	    return <MobileHome />;
21	  }
22	
23	  if (deviceMode === 'tablet') {
24	    return <TabletHome />;
25	  }
26	
27	  if (loading || !selectedStore) {
28	    return (
29	      <div className="min-h-screen w-full bg-white dark:bg-[#0A0A0A] flex items-center justify-center">
30	        <div className="text-center space-y-4">
31	          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#57715B] mx-auto"></div>
32	          <p className="text-muted-foreground">Carregando...</p>
33	        </div>
34	      </div>
35	    );
36	  }
37	
38	  return <DashboardAnalytics />;
39	}
