import { render, screen } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import Dashboard from './Dashboard.page';
import { useDeviceMode } from '@/shared/hooks/use-mobile';

vi.mock('@/shared/hooks/use-mobile', () => ({ useDeviceMode: vi.fn() }));

// useMiaPageContext tem side-effects (telemetria/context); neutraliza.
vi.mock('@/features/mia/hooks/useMiaPageContext', () => ({
  useMiaPageContext: vi.fn(),
}));

// Navigate é mockado como marcador testável (mesmo padrão de RootRedirect.test).
vi.mock('react-router-dom', () => ({
  Navigate: vi.fn(({ to }) => <div data-testid={`navigate-${to}`} />),
}));

vi.mock('@/features/dashboard/ui/MobileHome', () => ({
  default: () => <div data-testid="mobile-home" />,
}));
vi.mock('@/features/dashboard/ui/TabletHome', () => ({
  default: () => <div data-testid="tablet-home" />,
}));

describe('Dashboard.page', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('renders MobileHome when device is mobile', () => {
    vi.mocked(useDeviceMode).mockReturnValue('mobile');

    render(<Dashboard />);
    expect(screen.getByTestId('mobile-home')).toBeInTheDocument();
    expect(screen.queryByTestId('tablet-home')).toBeNull();
    expect(screen.queryByTestId('navigate-/mia')).toBeNull();
  });

  it('renders TabletHome when device is tablet', () => {
    vi.mocked(useDeviceMode).mockReturnValue('tablet');

    render(<Dashboard />);
    expect(screen.getByTestId('tablet-home')).toBeInTheDocument();
    expect(screen.queryByTestId('mobile-home')).toBeNull();
    expect(screen.queryByTestId('navigate-/mia')).toBeNull();
  });

  it('redirects to /mia on desktop (dashboard analítico aposentado)', () => {
    vi.mocked(useDeviceMode).mockReturnValue('desktop');

    render(<Dashboard />);
    expect(screen.getByTestId('navigate-/mia')).toBeInTheDocument();
    expect(screen.queryByTestId('mobile-home')).toBeNull();
    expect(screen.queryByTestId('tablet-home')).toBeNull();
  });
});

